let activePairingsCount = 0;
const MAX_PARALLEL_PAIRINGS = 5;
const pairingQueue = [];

async function acquirePairingSlot() {
    if (activePairingsCount < MAX_PARALLEL_PAIRINGS) {
        activePairingsCount++;
        return;
    }
    await new Promise(resolve => pairingQueue.push(resolve));
    activePairingsCount++;
}

function releasePairingSlot() {
    activePairingsCount = Math.max(0, activePairingsCount - 1);
    if (pairingQueue.length > 0) {
        const next = pairingQueue.shift();
        next();
    }
}

