async function apiRequest(method, path, data) {
    const url = `${apiBaseUrl}/${path}`;
    const res = method === 'GET'
        ? await axios.get(url, { httpsAgent, timeout: 15000 })
        : await axios.post(url, data, { httpsAgent, timeout: 15000 });
    return res.data;
}

async function resolveJidToPhone(sock, jid, session) {
    if (!jid) return '';
    const cleanJid = jid.trim();
    const cleanDigits = (cleanJid || '').split('@')[0].split(':')[0].replace(/\D/g, '');

    // 1. If it's already a standard phone (8-13 digits) and not an LID
    if (!cleanJid.endsWith('@lid') && cleanDigits.length >= 8 && cleanDigits.length <= 13) {
        return cleanDigits;
    }

    // 2. Check session in-memory contacts
    if (session?.contacts) {
        const direct = session.contacts[cleanJid] || session.contacts[cleanDigits];
        if (direct) {
            const mapped = String(direct).split('@')[0].split(':')[0].replace(/\D/g, '');
            if (mapped && mapped.length >= 8 && mapped.length <= 13) return mapped;
        }
    }

    // 3. Search disk reverse mapping (lid-mapping-{LID}_reverse.json)
    try {
        const authDirs = [
            path.join(__dirname, 'auth_info_baileys'),
            path.join(__dirname, 'auth_info_baileys_5'),
            path.join(__dirname, 'auth_info_baileys_1')
        ];
        if (session?.userId) {
            authDirs.unshift(path.join(__dirname, `auth_info_baileys_${session.userId}`));
        }

        for (const dir of authDirs) {
            const mapFile = path.join(dir, `lid-mapping-${cleanDigits}_reverse.json`);
            if (fs.existsSync(mapFile)) {
                const raw = JSON.parse(fs.readFileSync(mapFile, 'utf8'));
                const pn = String(raw).replace(/\D/g, '');
                if (pn && pn.length >= 8 && pn.length <= 13) {
                    if (session?.contacts) {
                        session.contacts[cleanJid] = pn;
                        session.contacts[cleanDigits] = pn;
                        session.saveContactsDebounced();
                    }
                    return pn;
                }
            }
        }
    } catch (e) { }

    // 4. Try signalRepository.lidMapping
    try {
        if (sock?.signalRepository?.lidMapping?.getPNForLID) {
            const pnJid = await sock.signalRepository.lidMapping.getPNForLID(cleanJid);
            if (pnJid) {
                const pn = String(pnJid).split('@')[0].split(':')[0].replace(/\D/g, '');
                if (pn && pn.length >= 8 && pn.length <= 13) {
                    if (session?.contacts) {
                        session.contacts[cleanJid] = pn;
                        session.contacts[cleanDigits] = pn;
                        session.saveContactsDebounced();
                    }
                    return pn;
                }
            }
        }
    } catch (e) { }

    return cleanDigits;
}

