    async cleanupSocket() {
        this.cancelReconnectTimer();
        if (this.contactSaveTimer) {
            clearTimeout(this.contactSaveTimer);
            this.contactSaveTimer = null;
        }
        if (this.sock) {
            try {
                this.sock.ev.removeAllListeners();
                if (this.sock.ws) this.sock.ws.close();
            } catch (e) { }
            this.sock = null;
        }
    }

    enqueueMessage(to, text, resolve, reject) {
        this.outgoingQueue.push({ to, text, resolve, reject });
        this.processOutgoingQueue();
    }

    async processOutgoingQueue() {
        if (this.isProcessingOutgoing || this.outgoingQueue.length === 0) return;
        this.isProcessingOutgoing = true;

        while (this.outgoingQueue.length > 0) {
            const job = this.outgoingQueue.shift();
            if (this.state !== STATES.CONNECTED || !this.sock?.user) {
                job.reject(new Error('Session not connected'));
                continue;
            }

            try {
                await this.sock.sendMessage(`${job.to}@s.whatsapp.net`, { text: job.text });
                metrics.messagesSent++;
                this.outboundMessages++;
                this.lastActiveTimestamp = Date.now();
                job.resolve({ success: true });
            } catch (e) {
                job.reject(e);
            }
            await new Promise(r => setTimeout(r, 600)); // Rate limit 600ms per outgoing message
        }

        this.isProcessingOutgoing = false;
    }
